import glob, pynwb, numpy as np

# Get all unique anno_names for good units and see how they map
nwb_files = sorted(glob.glob('/app/data/sub-*/sub-*_ses-*.nwb'))

# Sample a few sessions to get anno_name distribution
anno_counts = {}
for fpath in nwb_files[:20]:  # sample 20 sessions
    io = pynwb.NWBHDF5IO(fpath, 'r')
    nwb = io.read()
    units = nwb.units
    classifications = np.array(units['classification'][:])
    anno_names = np.array(units['anno_name'][:])
    good_mask = classifications == 'good'
    for anno in anno_names[good_mask]:
        anno_counts[anno] = anno_counts.get(anno, 0) + 1
    io.close()

# Check which annotations contain 'thalamus' in our mapping
from convert_data import map_anno_to_region
thalamus_annos = {}
midbrain_annos = {}
unmapped = {}
for anno, count in sorted(anno_counts.items(), key=lambda x: -x[1]):
    region = map_anno_to_region(anno)
    if region == 'Thalamus':
        thalamus_annos[anno] = count
    elif region == 'Midbrain':
        midbrain_annos[anno] = count
    elif region is None:
        unmapped[anno] = count

print("=== THALAMUS annotations ===")
for a, c in sorted(thalamus_annos.items(), key=lambda x: -x[1])[:15]:
    print(f"  {a}: {c}")

print("\n=== MIDBRAIN annotations ===")
for a, c in sorted(midbrain_annos.items(), key=lambda x: -x[1])[:15]:
    print(f"  {a}: {c}")

print("\n=== UNMAPPED annotations ===")
for a, c in sorted(unmapped.items(), key=lambda x: -x[1])[:20]:
    print(f"  {a}: {c}")
PYEOF

